function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Paint a rectangle on the green hills
  brush.fill("#5e4b1d", 1); // Green hills
  brush.beginShape(); // Start of a shape
  brush.vertex(0, 0); // Top left corner
  brush.vertex(400, 0); // Top right corner
  brush.vertex(200, 200); // Hill top
  brush.vertex(0, 200); // Hill top
  brush.endShape(true); // End of shape

  // Paint a sun
  brush.fill("#f9b925", 0.5); // Sun
  brush.beginShape(); // Start of a shape
  brush.vertex(300, 100); // Top of the sun
  brush.vertex(100, 100); // Top of the sun
  brush.vertex(200, 50); // Sun disk top
  brush.vertex(400, 50); // Sun disk top
  brush.vertex(300, 100); // Top of the sun
  brush.endShape(true); // End of shape
}
```

