function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#e057b8");
  // Paints an overview of the hills, a green "mountains" jungle

  brush.fill("#040408", 100); // fill up hill to the peak peaks
  brush.fillTexture(1, 6); // brief texture on the top     
  brush.fillTexture(100, 280); // texture at the bottom
  brush.arc(240, 220, 400, 400); // top hill peak
  brush.fill("#ffffff", 65);
  brush.circle(240, 220, 100); // hill trunk
  brush.fill("#040404", 70);
  brush.fillTexture(150, 300); // light green grass
  brush.beginShape();
  brush.vertex(220, 250); // top left hill
  brush.vertex(240, 240); // middle left hill
  brush.vertex(260, 270); // middle right hill
  brush.vertex(230, 230); // bottom hill
  brush.endShape(true);
  // Paints grass top

  brush.fill("#00ffff", 25);
  brush.beginShape();
  brush.vertex(180, 285);
  brush.vertex(190, 270);
  brush.vertex(210, 270);
  brush.vertex(200, 285);
  brush.endShape(true);
  // Paints grass bottom   
  brush.fill("#00ffff", 50);
  brush.beginShape();
  brush.vertex(220, 335);
  brush.vertex(225, 350);
  brush.vertex(215, 350);
  brush.vertex(230, 340);
  brush.endShape(true);
  brush.fill("#ffffff", 65); // paint clear sky

  // Paints hill grass
  brush.beginShape();
  brush.vertex(450, 440); // top hill slope left green
  brush.vertex(380, 440); // middle left hill top
  brush.vertex(450, 400); // bottom left hill top
  brush.vertex(460, 350); // bottom hill
  brush.vertex(450, 330); // top left hill top
  brush.vertex(460, 380); // middle right hill top
  brush.vertex(400, 380); //

