Here's a p5.js sketch that paints a sunset over green hills using the `p5.brush` library.

```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4"); // Sky

  // Paint green hills
  brush.fill("#06b665", 50); // Green hills
  brush.beginShape();
  brush.vertex(0, 0); // Top left hill
  brush.vertex(400, 0); // Top right hill
  brush.vertex(200, 50); // Hill in the middle
  brush.endShape(true);

  // Paint a sunset
  brush.fill("#ff3636", 30); // Sunset
  brush.beginShape();
  brush.vertex(0, 100); // Top left sunset
  brush.vertex(400, 100); // Top right sunset
  brush.vertex(200, 150); // Sunset in the middle
  brush.endShape(true);
}

