function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky and hills
  brush.fill("#cfc6ff", 0.7);  // Sky blue
  brush.beginShape();
  brush.vertex(-200, 50);  // Top left hill
  brush.vertex(200, 50);  // Top right hill
  brush.vertex(200, 200);  // Top of hill
  brush.vertex(-200, 200);  // Top of hill
  brush.endShape(true);

  // Green hills
