  brush.beginShape();
  brush.vertex(-200, 50);  // Left hill
  brush.vertex(-200, 200);  // Top left hill
  brush.vertex(200, 200);  // Top of hill
  brush.vertex(-200, 250);  // Bottom left hill
  brush.endShape(true);

  // Sun
  brush.fill("#d2c8a7", 1);  // Sun
  brush.beginShape();
  brush.vertex(-50, 170);  // Top of sun
  brush.vertex(50, 170);  // Top of sun
  brush.vertex(50, 150);  // Top of sun
  brush.vertex(150, 150);  // Top of sun
  brush.endShape(true);

  // Ground and hills
  brush.fill("#a1b2a0", 0.4);  // Ground
  brush.beginShape();
  brush.vertex(0, 250);  // Left ground
  brush.vertex(200, 250);  // Middle left ground
  brush.vertex(200, 300);  // Middle right ground
  brush.vertex(0, 300);  // Right ground
  brush.endShape(true);

  // Sun
  brush.fill("#d2c8a7", 1);  // Sun
  brush.beginShape();
  brush.vertex(0, 170);  // Top of sun
  brush.vertex(100, 170);  // Top of sun
  brush.vertex(100, 150);  // Top of sun
  brush.vertex(100, 100);  // Top of sun
  brush.endShape(true);
}
