  brush.beginShape();
  brush.vertex(200, 50);  // Top of sun
  brush.vertex(100, 50);  // Top of sun
  brush.vertex(150, 30);  // Top of sun
  brush.vertex(100, 30);  // Top of sun
  brush.endShape(true);

  // Paint the sun's rays
  brush.fill("#ff0000", 0.6);  // Sun's rays red
  brush.beginShape();
  brush.vertex(200, 150);  // Top of sun ray
  brush.vertex(100, 150);  // Top of sun ray
  brush.vertex(150, 150);  // Top of sun ray
  brush.vertex(100, 150);  // Top of sun ray
  brush.endShape(true);

  // Paint the horizon
