  brush.beginShape();
  brush.vertex(50, 300);  // Left horizon
  brush.vertex(250, 300);  // Right horizon
  brush.vertex(50, 350);  // Left horizon
  brush.vertex(250, 350);  // Right horizon
  brush.endShape(true);
}
